-- Jeere Connect — the two demo stores of the custom sites (concepts/joshua-cooker/, concepts/sonia-luxury-hair/).
-- Project « Jeere » (ref aezchxfvzfoqlvzchqyk), table public.stores (migration create_jeere_stores).
-- NOT applied automatically: run it once in the SQL editor (it can be run again: on conflict (slug) it
-- replaces the fiche and keeps the store published; the owner of an existing row never changes, trigger
-- jeere_stores_touch).
--
-- Owner: 706a1f96-346c-4b74-83fe-2b683517f54d (her account: the stores then show up in « Mes boutiques » and she edits names, prices
-- and descriptions in the Jeere editor; the custom sites read them from the published fiche).
--
-- Each fiche is a normal Jeere store config: JEERE_DATA.defaultConfig(template, niche) from creer/data.js
-- (Joshua: treichville + food; Sonia: cocody + hair), the store's own name, texts and products, then
-- JEERE_DATA.normalizeConfig, exactly what JeerePublish.ficheOf publishes. The sample reviews and stock
-- photos of the templates are taken out.
--
-- Before sharing the stores:
--   - store.whatsapp is empty: the Jeere cart then says the store does not take orders yet. Set the number in
--     the editor (or here, "whatsapp":"+225…") so « Commander sur WhatsApp » sends the order.
--   - the delivery zones and fees are the template's sample communes: check them in the editor.
--   - product ids are p1, p2… (Jeere's format, kept by normalizeConfig): the sites bind to them with
--     data-jeere-product="p1". Joshua's photos are https URLs on kreeative.xyz in products[].image: Jeere Connect
--     shows them, the Jeere store page draws its illustration instead (it only shows photos uploaded to Jeere),
--     and a republish from the editor drops them (the custom site then keeps its own photos).

begin;

-- Joshua Cooker · https://jeere.kreeative.xyz/b/joshua-cooker · products p1 Poulet persil 7000, p2 La formule complète 9000, p3 Le plateau à partager 25000
insert into public.stores (owner, slug, fiche, show_badge, published)
values ('706a1f96-346c-4b74-83fe-2b683517f54d', 'joshua-cooker', $jeere${"version":1,"template":"treichville","store":{"name":"Joshua Cooker","tagline":"Le poulet persil du chef, à commander à Abidjan","whatsapp":"","city":"Abidjan","niche":"food"},"theme":{"palette":"menthe","fonts":"audacieux","radius":"none","buttons":"solid","intensity":"vivid","colors":{"bg":"#FBFAF6","surface":"#FFFFFF","text":"#0B0B0A","muted":"#5C5B57","accent":"#0E3B2C","onAccent":"#FFFFFF"}},"payments":{"wave":true,"orange":true,"mtn":true,"moov":false,"cod":true,"card":false},"sections":[{"id":"s1","type":"announcement","enabled":true,"settings":{"text":"Le poulet persil de Joshua Cooker, livré à Abidjan"}},{"id":"s2","type":"hero","enabled":true,"settings":{"kicker":"Chef culinaire professionnel · Abidjan","title":"Poulet persil","text":"Le plat signature de Joshua Cooker. Commandez-le à Abidjan, ou venez le manger sur place dans ses lieux.","button":"Voir la carte","image":null,"photo":null}},{"id":"s3","type":"products","enabled":true,"settings":{"title":"La carte","limit":8,"columns":3}},{"id":"s4","type":"whatsapp","enabled":true,"settings":{"title":"Booker Joshua Cooker","text":"Mariage, anniversaire, pop-up, collab de marque ou vidéo : écrivez au chef sur WhatsApp.","button":"Écrire au chef"}},{"id":"s7","type":"delivery","enabled":true,"settings":{"title":"Nos frais de livraison","text":"Les frais de livraison de votre commune s’ajoutent à la commande.","zones":[{"name":"Abobo","fee":2500},{"name":"Adjamé","fee":2000},{"name":"Attécoubé","fee":2500},{"name":"Cocody","fee":1500},{"name":"Koumassi","fee":2000},{"name":"Marcory","fee":1500}]}},{"id":"s8","type":"about","enabled":true,"settings":{"title":"Le chef","text":"Cuisinier professionnel basé à Abidjan, Joshua s’est fait connaître avec un plat devenu sa signature : le poulet persil, doré, nappé d’une sauce crémeuse au persil, servi avec attiéké, salade d’oignons et piment.\n\nSa cuisine se vit ensemble : dans ses lieux à Abidjan, et pendant sa tournée, en Afrique de l’Ouest, au Cameroun et en France.","image":null,"photo":null}}],"products":[{"id":"p1","name":"Poulet persil","price":7000,"category":"Plats","badge":"best","art":"plate","color":"#CFE3D6","description":"Poulet doré, sauce crémeuse au persil, salade d'oignons, piment.","image":"https://kreeative.xyz/concepts/joshua-cooker/img/plate6b.webp","photo":null,"alt":"Poulet persil"},{"id":"p2","name":"La formule complète","price":9000,"category":"Plats","badge":null,"art":"plate","color":"#E4EFE8","description":"Poulet persil, attiéké, salade d'oignons et piment maison.","image":"https://kreeative.xyz/concepts/joshua-cooker/img/plat4-crop.webp","photo":null,"alt":"La formule complète"},{"id":"p3","name":"Le plateau à partager","price":25000,"category":"Plats","badge":null,"art":"plate","color":"#D9E8DF","description":"Le grand plat pour la table, avec attiéké pour 4 personnes.","image":"https://kreeative.xyz/concepts/joshua-cooker/img/plat3-crop.webp","photo":null,"alt":"Le plateau à partager"}],"pages":[{"id":"pg1","title":"À propos","slug":"a-propos","body":"Cuisinier professionnel basé à Abidjan, Joshua s’est fait connaître avec un plat devenu sa signature : le poulet persil, doré, nappé d’une sauce crémeuse au persil, servi avec attiéké, salade d’oignons et piment.\n\nSa cuisine se vit ensemble : dans ses lieux à Abidjan, et pendant sa tournée, en Afrique de l’Ouest, au Cameroun et en France.\n\nUne question avant de commander ? Écrivez au chef sur WhatsApp.","inMenu":true,"inFooter":true},{"id":"pg2","title":"Livraison et retours","slug":"livraison-et-retours","body":"Nous livrons à Abidjan. Les frais dépendent de votre commune : ils s’affichent avant que vous commandiez.\n\nUne question sur la livraison ou un produit reçu abîmé ? Écrivez-nous sur WhatsApp : nous trouvons une solution ensemble.","inMenu":false,"inFooter":true},{"id":"pg3","title":"Contact","slug":"contact","body":"Le plus simple pour nous joindre, c’est WhatsApp : écrivez-nous ou envoyez un message vocal.\n\nPour une commande déjà passée, envoyez-nous ce que vous avez commandé : nous vous disons où elle en est.","inMenu":true,"inFooter":true},{"id":"pg4","title":"Conditions de vente","slug":"conditions-de-vente","body":"À adapter : ce texte est un modèle général. Faites-le vérifier par un juriste avant d’ouvrir votre boutique, puis supprimez ce paragraphe.\n\nVendeur : Joshua Cooker, à Abidjan, en Côte d’Ivoire. Pour toute question, écrivez-nous sur WhatsApp (voir la page « Contact »).\n\nCommande : votre commande est ferme quand nous vous la confirmons, sur cette boutique ou sur WhatsApp. Si un produit n’est plus disponible, nous vous prévenons et nous vous proposons un autre produit ou le remboursement.\n\nPrix : les prix sont indiqués en francs CFA (FCFA), toutes taxes comprises. Les frais de livraison dépendent de votre commune et s’affichent avant le paiement. Le prix à payer est celui affiché au moment de la commande.\n\nPaiement : vous payez avec l’un des moyens proposés au moment de la commande, par mobile money, par carte ou à la livraison. Les paiements en ligne sont traités par un partenaire de paiement agréé. Nous ne vous demandons jamais votre code secret : ne le donnez à personne, pas même au livreur.\n\nLivraison : les délais et les frais sont indiqués sur la page « Livraison et retours ». Vérifiez votre colis à la réception, devant le livreur.\n\nRetours et remboursements : les conditions sont expliquées sur la page « Livraison et retours ». Un remboursement accepté est fait par mobile money ou par le moyen de paiement utilisé.\n\nDonnées personnelles : votre nom, votre numéro et votre adresse servent uniquement à traiter et à livrer votre commande. Ils ne sont ni vendus ni partagés, sauf avec le livreur et le partenaire de paiement. Pour les faire modifier ou supprimer, écrivez-nous.\n\nLitiges : en cas de désaccord, contactez-nous d’abord ; nous cherchons toujours une solution à l’amiable. Ces conditions sont soumises au droit ivoirien.","inMenu":false,"inFooter":true}]}$jeere$::jsonb, true, true)
on conflict (slug) do update set fiche = excluded.fiche, published = true;

